      "rank": 1,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision measurement by combining extraordinary accuracy with broad scientific reach.",
        "attribution": "Katori introduced the magic-wavelength lattice-clock concept, while Ye made decisive experimental advances and established its performance.",
        "maturity": "Independent laboratories have demonstrated robust clocks and their value for metrology, tests of fundamental physics, and geodesy.",
        "uncertainties": []
      }
    },
    {
      "rank": 2,
      "ballot_id": "B056",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics made strong, controllable light-matter interaction available on a chip and opened a major experimental quantum platform.",
        "attribution": "Blais supplied the defining theoretical framework; Wallraff and Schoelkopf gave landmark experimental realization and established its physical utility.",
        "maturity": "The regime is reproduced across many laboratories and underlies a substantial body of quantum-optics and quantum-information experiments.",
        "uncertainties": [
          "Its proximity to the 2025 prize for superconducting circuits requires careful assessment of whether the recognized discovery is sufficiently distinct."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Carlton M. Caves",
        "Nergis Mavalvala",
        "Roman Schnabel"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light converted a fundamental quantum-optical resource into a demonstrable improvement of interferometric measurement.",
        "attribution": "Caves established the quantum-measurement principle, while Mavalvala and Schnabel were central to its development and implementation in precision interferometry.",
        "maturity": "Squeezing is now a proven operational component of gravitational-wave observatories and precision optical experiments.",
        "uncertainties": [
          "Credit for the full experimental pathway is necessarily distributed across several laboratories."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological-insulator framework revealed a qualitatively new class of electronic matter.",
        "attribution": "Kane and Mele provided the seminal theoretical prediction, and Molenkamp led a decisive experimental observation of the quantum spin Hall regime.",
        "maturity": "The topological classification and experimental phenomena have been extensively verified and have reshaped condensed-matter physics.",
        "uncertainties": [
          "The appropriate balance between foundational theorists and multiple experimental discoverers remains difficult."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B047",
      "proposed_laureates": [
        "Markus Aspelmeyer",
        "Oskar Painter",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics brought mechanical motion into the quantum-control regime and created an important bridge between quantum optics and mesoscopic devices.",
        "attribution": "Aspelmeyer, Painter, and Kippenberg made distinct, central contributions to establishing and developing the experimental field.",
        "maturity": "Ground-state cooling, quantum-limited measurements, and coherent control have been reproduced widely.",
        "uncertainties": [
          "The discovery is a broad field development rather than a single sharply bounded experiment."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold-atom realizations of Hubbard physics made strongly correlated lattice models experimentally controllable in a remarkable new way.",
        "attribution": "Bloch and Greiner made pioneering experimental platforms and demonstrations, while Zoller supplied essential quantum-simulation concepts.",
        "maturity": "The approach is mature, broadly reproduced, and has enabled quantitative studies inaccessible in conventional materials.",
        "uncertainties": [
          "Attribution spans a large theoretical and experimental community, including other nominees."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B059",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and geometric phase exposed profound operational roles of phase and gauge structure throughout quantum physics.",
        "attribution": "Aharonov is central to the original nonlocal phase effect, and Berry identified the broadly applicable adiabatic geometric phase.",
        "maturity": "Both effects are experimentally established and influential across quantum, condensed-matter, and optical physics.",
        "uncertainties": [
          "They are historically and conceptually distinct discoveries, despite their shared emphasis on quantum phase."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction supplied the conceptual means by which fragile quantum information can, in principle, be protected and processed fault tolerantly.",
        "attribution": "Shor and Steane introduced foundational codes, while Kitaev provided the topological-code framework with exceptional physical significance.",
        "maturity": "Core principles are experimentally tested and now guide major hardware programs, though scalable fault tolerance remains incomplete.",
        "uncertainties": [
          "Whether the field has yet reached the experimental maturity expected for a prize remains an important question."
        ]
      }
    }
  ]
}
